// Control inputs arrive with msg.topic = the flow-context key
// (selNode | selBatch | selKind | selSlug).
if (msg.payload !== undefined && msg.topic) {
    flow.set(msg.topic, msg.payload);
}
return null;

// In: verb from the control buttons: label | discard | reset | start | normal | fault.
// Out 1: the publish message (payload + topic) -> mqtt out.
// Out 2: the last-command display line.
// UNS bases must match nodes/*/main.cpp UNS_BASE and uns/uns.json.
const BASES = {
    "g100-01": "v1/Plant01/Motor-Test-Area/Line1/Power-Node-01",
    "vib-01":  "v1/Plant01/Motor-Test-Area/Line1/Vibration-Node-01",
};
const verb = String(msg.payload);
const dev = flow.get("selNode") || "g100-01";
const base = BASES[dev];
if (!base) {
    node.warn("unknown node selection: " + dev);
    return [null, { payload: { line: "unknown node selection: " + dev } }];
}

let out = null, line = "";
if (verb === "label") {
    const slug = String(flow.get("selSlug") || "").trim();
    if (!slug) {
        node.warn("label: no condition label entered");
        return [null, { payload: { line: "label: no condition label entered" } }];
    }
    // kind defaults to FAULT in the firmware; be explicit here
    out = { action: "label", label: slug, by: "human",
            kind: flow.get("selKind") || "fault" };
    const batch = String(flow.get("selBatch") || "").trim();
    if (batch) out.batch = batch;   // stored-batch flow; omit = live episode
    line = dev + " <- LABEL " + slug + " [" + out.kind + "]"
           + (batch ? " batch " + batch : "");
} else if (verb === "discard") {
    const batch = String(flow.get("selBatch") || "").trim();
    if (!batch) {
        node.warn("discard: no batch id entered");
        return [null, { payload: { line: "discard: no batch id entered" } }];
    }
    out = { action: "discard", batch: batch };
    line = dev + " <- DISCARD batch " + batch;
} else if (verb === "reset") {
    // factory wipe: arm/confirm within 10 s (the human-approval contract)
    const armed = flow.get("resetArm") || 0;
    if (Date.now() - armed > 10000) {
        flow.set("resetArm", Date.now());
        return [null, { payload: { line: "RESET ARMED on " + dev
            + " - press RESET again within 10 s to wipe it" } }];
    }
    flow.set("resetArm", 0);
    out = { action: "reset" };
    line = dev + " <- RESET (factory wipe)";
} else {
    out = { action: verb };         // start | normal | fault
    line = dev + " <- " + verb.toUpperCase();
}
return [{ payload: out, topic: base + "/Action/feedback" },
        { payload: { line: line } }];

// Column 1: merges State/condition + State/keepalive for BOTH nodes into
// one banner block per node. The node id comes from the UNS path in msg.topic.
function nodeOf(t) {
    if (t.indexOf("Power-Node-01") >= 0) return "g100-01";
    if (t.indexOf("Vibration-Node-01") >= 0) return "vib-01";
    return null;
}
const t = String(msg.topic || "");
const p = msg.payload;
const dev = nodeOf(t);
if (p !== "heartbeat" && dev && p && typeof p === "object") {
    if (t.indexOf("/State/condition") >= 0) {
        flow.set("cond_" + dev, {
            state: p.state || "?", condition_id: p.condition_id || "-",
            confidence: (typeof p.confidence === "number") ? p.confidence : null,
            episode_s: (typeof p.episode_s === "number") ? p.episode_s : 0,
            batch: p.batch || "",
            kind: p.kind || "",
            ts: Date.now()
        });
        if (p.batch) flow.set("ask_" + dev, p.batch);
        else if (p.condition_id === "unknown") flow.set("ask_" + dev, "");
    } else if (t.indexOf("/State/keepalive") >= 0) {
        flow.set("ka_" + dev, { ts: Date.now(), rssi: p.rssi });
    }
}
const rows = [];
for (const d of ["g100-01", "vib-01"]) {
    const c = flow.get("cond_" + d);
    const k = flow.get("ka_" + d);
    const kaAge = k ? Math.round((Date.now() - k.ts) / 1000) : null;
    const online = kaAge !== null && kaAge <= 30;
    const age = c ? Math.round((Date.now() - c.ts) / 1000) : null;
    const st = c ? c.state : "?";
    const cid = c ? c.condition_id : "-";
    const batch = c && c.batch ? " " + c.batch : "";
    const kind = (c && c.kind) || "";
    let cls = "ok", badge = "?", l2 = "";
    if (!online) { cls = "off"; badge = "OFFLINE"; l2 = "no keepalive beat"; }
    else if (st === "alarm") {
        cls = "alarm"; badge = "ALARM" + batch;
        l2 = cid === "unknown" ? "unlabeled condition - answer with LABEL"
                                : "alarm episode";
    } else if (kind === "fault") {
        // a labeled fault recognized while quiet: red by its label (the
        // State/condition kind), not by the alarm gate
        cls = "alarm"; badge = "OK" + batch;
        l2 = "learned fault recognized while quiet";
    } else if (cid === "unknown") {
        cls = "attention"; badge = "OPEN ASK" + batch;
        l2 = "unlabeled condition - answer with LABEL";
    } else if (st === "learn") { cls = "learn"; badge = "LEARNING";
        l2 = "capturing normal-behaviour statistics"; }
    else if (st === "idle") { cls = "learn"; badge = "IDLE";
        l2 = "send START to begin learning"; }
    else if (st === "ok") { cls = "ok"; badge = "OK"; l2 = "monitoring - quiet"; }
    else { cls = "ok"; badge = st.toUpperCase(); l2 = ""; }
    rows.push({ id: d, badge: badge, cls: cls, l2: l2, cond: cid, kind: kind,
        conf: (c && c.confidence !== null) ? Math.round(c.confidence * 100) + "%" : "-",
        ep: (c && c.episode_s) ? c.episode_s + " s" : "-",
        age: (age !== null) ? age + " s" : "-",
        rssi: (online && k && typeof k.rssi === "number") ? k.rssi + " dBm" : "-" });
}
return { payload: rows };

// Column 2: State/event from EITHER node -> one shared rolling log.
// batch = the node's live ask id (State/condition batch): a label row
// shows the batch it answered; a close row shows a batch still pending
// for late labeling; open rows show '-' (the batch matures after open).
function nodeOf(t) {
    if (t.indexOf("Power-Node-01") >= 0) return "g100-01";
    if (t.indexOf("Vibration-Node-01") >= 0) return "vib-01";
    return null;
}
const dev = nodeOf(String(msg.topic || ""));
if (!dev) return null;
const p = msg.payload || {};
const ts = new Date().toISOString().replace("T", " ").slice(0, 19);
const ask = flow.get("ask_" + dev) || "";
const row = { ts: ts, node: dev, event: p.event || "",
    condition: p.condition_id || "", severity: p.severity || "",
    dur: (p.duration_s === undefined || p.duration_s === null) ? "-"
         : p.duration_s + " s",
    batch: ask || "-", summary: p.summary || "" };
let rows = flow.get("eventRows") || [];
rows.unshift(row);
if (rows.length > 20) rows = rows.slice(0, 20);
flow.set("eventRows", rows);
if (p.event === "label") flow.set("ask_" + dev, "");
return { payload: rows };

// AI assistant: dashboard question + live flow context -> Z.ai chat completion.
// Env (screenflow service in docker-compose.override.yml): ZAI_API_KEY, ZAI_MODEL (default glm-5.3-flash).
// msg.auto === true means this request was triggered by the alarm watcher (ai_fn_watch).
// The reply may end with an {"ai_action":{...}} block: ai_fn_reply validates and
// publishes it (label | discard | normal | fault; reset/start are refused).
// The request body is kept in ai_last_req so ai_fn_reply can retry once on
// transient Z.ai gateway errors ("no response from server").
const key = env.get('ZAI_API_KEY') || '';
const model = env.get('ZAI_MODEL') || 'glm-5.3-flash';
const q = String(msg.payload || '').trim();
if (!q) return null;

let h = flow.get('ai_history') || [];
h.push({ ts: new Date().toISOString().replace('T', ' ').slice(0, 19), role: 'user', text: q, auto: msg.auto === true });
if (h.length > 30) h = h.slice(-30);
flow.set('ai_history', h);

if (!key) {
    h.push({ ts: '', role: 'assistant', text: 'ZAI_API_KEY is not set. Add it to the screenflow service env in docker-compose.override.yml, then: bash bin/compose.sh up -d screenflow', err: true });
    flow.set('ai_history', h);
    return [null, { payload: h }];
}

function condOf(d) {
    const c = flow.get('cond_' + d);
    const k = flow.get('ka_' + d);
    if (!c && !k) return null;
    return { node: d,
        online: k ? ((Date.now() - k.ts) <= 30000) : false,
        state: c ? c.state : '?',
        condition_id: c ? c.condition_id : '-',
        kind: (c && c.kind) || '',
        confidence: c ? c.confidence : null,
        episode_s: c ? c.episode_s : 0,
        open_batch: (c && c.batch) || '',
        keepalive_age_s: k ? Math.round((Date.now() - k.ts) / 1000) : null };
}
// slugs already labeled on each node (from the event log): the model must
// reuse these instead of inventing near-duplicates (skills.md Skill 2)
function knownOf(d) {
    const rows = flow.get('eventRows') || [];
    const out = [];
    for (const r of rows) {
        if (r.node === d && r.event === 'label' && r.condition &&
            out.indexOf(r.condition) < 0) out.push(r.condition);
    }
    return out;
}
const context = {
    nodes: ['g100-01', 'vib-01'].map(function (d) {
        const n = condOf(d);
        if (n) n.known_conditions = knownOf(d);
        return n;
    }).filter(Boolean),
    recent_events: (flow.get('eventRows') || []).slice(0, 10)
};

// prompt kept VERY short (2026-11-27: the watch request with the long
// prompt kept tripping the gateway on non-streamed calls; short manual
// questions always worked). Labeling is operator-driven ONLY: the model
// never labels on its own - the operator says normal/fault + the slug;
// ai_fn_reply enforces it (auto requests cannot carry actions at all).
let sys = 'You are the UNS machine dashboard assistant. Answer from the JSON data '
    + 'in the user message only, in 1-3 short sentences. Plain text, no markdown. '
    + 'To label: ONLY when the operator names the condition and says normal or fault, append one block per affected node (both nodes of the machine = two blocks) and nothing after it: '
    + '{"ai_action":{"action":"label","label":"speed_1","kind":"normal","batch":"P0001","node":"g100-01"}} '
    + 'batch = the node open_batch when present; node = g100-01 or vib-01; label = short snake_case. '
    + 'Never send the block unless the operator named the condition and kind. Never send any other action.';
const msgs = [{ role: 'system', content: sys }];
for (const m of h.filter(function (x) { return !x.err; }).slice(-8)) {
    msgs.push({ role: m.role, content: m.text });
}
const lastUser = msgs[msgs.length - 1];
if (lastUser && lastUser.role === 'user') {
    lastUser.content = lastUser.content + '\n\nLive data (JSON):\n' + JSON.stringify(context);
}

// single-flight (2026-11-27 log): the gateway drops concurrent
// connections from one key (double-watch ETIMEDOUT), so ONE request is in
// flight; the rest queue - manual questions at the FRONT, watch triggers
// at the back, cap 4 (overflow drops the oldest). A stuck slot
// self-heals after 180 s without a reply.
// docs.z.ai (chat-completion + thinking-mode pages, checked 2026-11-27):
// glm-5.3-flash runs FORCED thinking - thinking.type can only be
// 'enabled' and the depth knob is reasoning_effort (flash supports
// low|high|max; server DEFAULT = max). Max-effort reasoning on
// non-streamed calls caused the ETIMEDOUT / no-response-from-server /
// 200-empty failures, so pin it LOW; ZAI_REASONING=high|max overrides.
// Thinking shares max_tokens (2026-11-27 curl proof: a 50-token cap
// produced reasoning_tokens 48, content "", finish_reason length).
const body = { model: model, messages: msgs, stream: false, temperature: 0.3,
    max_tokens: 2048,
    thinking: { type: 'enabled' },
    reasoning_effort: 'low' };
const effort = String(env.get('ZAI_REASONING') || '').toLowerCase();
if (effort === 'low' || effort === 'high' || effort === 'max')
    body.reasoning_effort = effort;
const busy = flow.get('ai_busy');
const stale = busy && Date.now() - (flow.get('ai_busy_ts') || 0) > 90000;
if (busy && !stale) {
    // manual questions queue at the FRONT (they always get the slot next).
    // Watch triggers take ONE queue slot and the newest replaces an older
    // pending watch analysis: both nodes alarming together analyze
    // back-to-back, seconds apart, instead of the second being dropped.
    let q = flow.get('ai_queue') || [];
    if (msg.auto === true) {
        q = q.filter(x => x.auto !== true);
        q.push({ body: body, auto: true });
    } else {
        q.unshift({ body: body, auto: false });
    }
    if (q.length > 4) q = q.slice(0, 4);
    flow.set('ai_queue', q);
    return [null, { payload: h }];         // queued: nothing sent this tick
}
// ai_last_req mirrors the IN-FLIGHT request only - a retry must never
// pick up a queued question's body (2026-11-27 overlap bug)
flow.set('ai_last_req', body);
flow.set('ai_busy', true);
flow.set('ai_busy_ts', Date.now());
msg.headers = { 'Content-Type': 'application/json', Authorization: 'Bearer ' + key };
msg.payload = body;
return [msg, { payload: h }];

// Extract the assistant reply (or the Z.ai error) into the chat log.
// WRITE PATH (agent/skills.md Skill 2+3): a trailing {"ai_action":{...}} block in
// the reply is validated, then published to Action/feedback with by=agent.
// Allowed: label | discard | normal | fault. NEVER reset | start (human-only
// non-negotiables). Sends AND refusals are logged in the chat (audit trail).
// TRANSIENT Z.ai failures (5xx / "no response from server") are retried once
// via output 3 -> ai_http; the request body comes from ai_last_req.
const BASES = {
    'g100-01': 'v1/Plant01/Motor-Test-Area/Line1/Power-Node-01',
    'vib-01':  'v1/Plant01/Motor-Test-Area/Line1/Vibration-Node-01'
};
const ALLOWED = ['label', 'discard', 'normal', 'fault'];
const BLOCKED = ['reset', 'start'];
function slugify(s) {
    return String(s).toLowerCase().replace(/[^a-z0-9]+/g, '_')
        .replace(/^_+|_+$/g, '').slice(0, 24);
}
let h = flow.get('ai_history') || [];   // let: the trim below reassigns h
const ts = new Date().toISOString().replace('T', ' ').slice(0, 19);
let text, pub = null, retry = null;
const isAuto = msg.auto === true;
// classify the Z.ai outcome: ok | transient (silent retries) | fatal (log)
// Transient = HTTP 5xx / connection errors (ETIMEDOUT etc.), the gateway's
// "no response from server", AND the empty 200 (HTTP ok, zero content) -
// all the same gateway give-up in different costumes (2026-11-27 logs).
// Transients retry up to 3 attempts (paced by the 3 s delay node) and stay
// OUT of the chat; after the last attempt a manual question shows one
// error row, a watch trigger stays silent (the alarm is on the banner).
const AI_MAX_TRIES = 3;
const rawErr = (msg.payload && msg.payload.error && msg.payload.error.message)
    || (typeof msg.payload === 'string' ? msg.payload : '')
    || (msg.error && msg.error.message) || '';
const ch = (msg.statusCode === 200 && msg.payload && msg.payload.choices && msg.payload.choices[0]) || null;
const content = (ch && ch.message && typeof ch.message.content === 'string') ? ch.message.content : '';
const emptyBody = msg.statusCode === 200 && !content.trim();
const transient = msg.statusCode !== 200 && (!msg.statusCode || msg.statusCode >= 500
    || /no response|timeout|etimedout|econn|overloaded|temporarily/i.test(rawErr));
if (emptyBody || transient) {
    const tries = (flow.get('ai_tries') || 0) + 1;
    flow.set('ai_tries', tries);
    if (flow.get('ai_last_req') && tries < AI_MAX_TRIES) {
        // silent retry: paced by the 3 s delay node on the retry wire
        const key = env.get('ZAI_API_KEY') || '';
        retry = { headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + key },
                  payload: flow.get('ai_last_req'), auto: isAuto };
    } else {
        flow.set('ai_tries', 0);
        if (!isAuto) {   // watch failures stay out of the chat by design
            if (emptyBody) {
                // content empty = the thinking phase ate the output budget
                // (finish_reason "length") or the gateway gave up. Report the
                // numbers so the cause is visible from the dashboard alone.
                const u = (msg.payload && msg.payload.usage) || {};
                const rt = (u.completion_tokens_details && u.completion_tokens_details.reasoning_tokens) || 0;
                text = 'Z.ai returned NO content after ' + AI_MAX_TRIES + ' attempts'
                    + ' (finish_reason=' + ((ch && ch.finish_reason) || '?')
                    + ', reasoning_tokens=' + rt + '/' + (u.completion_tokens || '?')
                    + '). Thinking ate the budget - raise max_tokens in ai_fn_build or set ZAI_REASONING=low.';
            } else {
                text = 'Z.ai error ' + msg.statusCode + ' after ' + AI_MAX_TRIES + ' attempts: ' + String(rawErr || 'request failed').slice(0, 300);
            }
            h.push({ ts: ts, role: 'assistant', text: text, err: true });
        }
    }
} else if (msg.statusCode !== 200) {   // fatal: 4xx etc. - no retry
    flow.set('ai_tries', 0);
    text = 'Z.ai error ' + msg.statusCode + ': ' + String(rawErr || 'request failed').slice(0, 300);
    h.push({ ts: ts, role: 'assistant', text: text, err: true });
} else {
    flow.set('ai_tries', 0);
    text = content;
    // find ALL ai_action blocks - the model sends one per node (skills.md:
    // a physical event opens asks on several nodes of one machine; answer
    // every open batch with the SAME slug). Strip them from the display text.
    const KEY = '{"ai_action"';
    const acts = [];
    let pos = text.indexOf(KEY);
    while (pos >= 0 && acts.length < 6) {
        let depth = 0, end = -1;
        for (let j = pos; j < text.length; j++) {
            if (text[j] === '{') depth++;
            else if (text[j] === '}') { depth--; if (depth === 0) { end = j + 1; break; } }
        }
        if (end < 0) { acts.push({ why: 'unterminated ai_action block (reply truncated?)' }); text = text.slice(0, pos); break; }
        let a = null, perr = '';
        try { a = JSON.parse(text.slice(pos, end)).ai_action; }
        catch (e) { perr = 'ai_action block is not valid JSON'; }
        acts.push((a && typeof a === 'object') ? { act: a } : { why: perr || 'block has no ai_action member' });
        text = (text.slice(0, pos) + text.slice(end)).replace(/```[a-z]*/g, '');
        pos = text.indexOf(KEY);
    }
    text = text.trim();
    h.push({ ts: ts, role: 'assistant', text: text });
    if (acts.length) {
        const refuse = function (r) {
            h.push({ ts: '', role: 'assistant', text: 'ACTION NOT SENT - ' + r, err: true });
        };
        const pubs = [];
        for (const a of acts) {
            if (a.why) { refuse(a.why); continue; }
            if (isAuto) {
                // watch requests are read-only: labeling is operator-driven
                // (the operator names the condition and kind). Drop silently;
                // debug sidebar only, nothing published, nothing in the chat.
                node.warn('ai: dropped an action block on a watch trigger - labeling is operator-only');
                continue;
            }
            const act = a.act;
            const dev = String(act.node || '');
            const verb = String(act.action || '');
            const k = flow.get('ka_' + dev);
            const cnd = flow.get('cond_' + dev);
            const online = !!(k && (Date.now() - k.ts) <= 30000);
            const st = cnd ? cnd.state : '?';
            const send = function (o) {
                const key = dev + '|' + JSON.stringify(o);
                if (flow.get('ai_last_act') === key) { refuse('duplicate of the last action already sent'); return; }
                flow.set('ai_last_act', key);
                pubs.push({ payload: o, topic: BASES[dev] + '/Action/feedback' });
                h.push({ ts: ts, role: 'assistant', text: 'WROTE to ' + dev + ': ' + JSON.stringify(o), act: true });
            };
            if (BLOCKED.indexOf(verb) >= 0) refuse(verb + ' is human-only (skills.md non-negotiable)');
            else if (ALLOWED.indexOf(verb) < 0) refuse('unknown action: ' + verb);
            else if (!BASES[dev]) refuse('unknown node: ' + dev);
            else if (!online) refuse(dev + ' is offline (keepalive stale) - publish would be lost');
            else if (verb === 'label') {
                const slug = slugify(String(act.label || ''));
                const batch = String(act.batch || '').trim();
                if (!slug) refuse('label: no label slug given');
                else if (batch && !/^[A-Za-z0-9]{1,11}$/.test(batch)) refuse('label: bad batch id: ' + batch);
                else if (!batch && !(cnd && (cnd.state === 'alarm' || cnd.condition_id === 'unknown'
        || cnd.condition_id === 'unidentified')))
    refuse('label: no batch id and no open episode on ' + dev);   // firmware: any open episode is live-labelable
                else if (st === 'idle' || st === 'learn' || st === '?') refuse('label: node state is ' + st + ' - labels wait for ok/alarm (skills.md Skill 3)');
                else {
                    const o = { action: 'label', label: slug, by: 'agent',
                                kind: (act.kind === 'normal') ? 'normal' : 'fault' };
                    if (batch) o.batch = batch;
                    send(o);
                }
            } else if (verb === 'discard') {
                const batch = String(act.batch || '').trim();
                if (!/^[A-Za-z0-9]{1,11}$/.test(batch)) refuse('discard: needs a valid batch id');
                else send({ action: 'discard', batch: batch, by: 'agent' });
            } else send({ action: verb, by: 'agent' });   // normal | fault: sparing governance
        }
        pub = pubs.length ? pubs : null;
    }
}
if (h.length > 30) h = h.slice(-30);
flow.set('ai_history', h);
let nextOut = null;
if (!retry) {
    // the flight slot frees only when no retry is pending; then pop the queue
    const q = flow.get('ai_queue') || [];
    const next = q.shift() || null;
    flow.set('ai_queue', q);
    if (next) {
        flow.set('ai_busy', true);
        flow.set('ai_busy_ts', Date.now());
        flow.set('ai_last_req', next.body);   // the popped request is now in flight
        const key = env.get('ZAI_API_KEY') || '';
        nextOut = { headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + key },
                    payload: next.body, auto: next.auto };
    } else {
        flow.set('ai_busy', false);
    }
}
return [{ payload: h }, pub, retry, nextOut];

// Store the typed question; the SEND button sends it.
if (msg.payload !== undefined) flow.set('ai_question', String(msg.payload).trim());
return null;

const q = String(flow.get('ai_question') || '').trim();
if (!q) return null;
msg.payload = q;
return msg;

// Fired from the State/condition MQTT inputs: wakes the assistant on a new alarm episode.
// Dedup: same node|condition|batch|ts_ms never re-triggers; plus a 60 s per-node cooldown.
const p = msg.payload;
if (!p || typeof p !== 'object' || p.state !== 'alarm') return null;
const t = String(msg.topic || '');
const dev = t.indexOf('Power-Node-01') >= 0 ? 'g100-01' : (t.indexOf('Vibration-Node-01') >= 0 ? 'vib-01' : null);
if (!dev) return null;
const key = dev + '|' + (p.condition_id || '') + '|' + (p.batch || '') + '|' + (p.ts_ms || '');
if (flow.get('ai_last_trigger') === key) return null;
const lastTs = flow.get('ai_auto_ts_' + dev) || 0;
if (Date.now() - lastTs < 60000) return null;
flow.set('ai_last_trigger', key);
flow.set('ai_auto_ts_' + dev, Date.now());
msg.auto = true;
msg.payload = 'Alarm just fired on ' + dev + ' (condition: ' + (p.condition_id || 'unknown') + ', confidence: ' + (typeof p.confidence === 'number' ? p.confidence : '?') + ', episode ' + (p.episode_s || 0) + ' s' + (p.batch ? ', batch ' + p.batch : '') + '). Analyse it for the operator.';
return msg;
